## solution

#### dynamic programming with memoization

```cpp
#include <vector>
#include <unordered_map>

bool arrayStepper(std::vector<int> numbers, int i, std::unordered_map<int, bool> &memo) {
  if (memo.count(i) > 0) {
    return memo[i];
  }

  if (i == numbers.size() - 1) {
    return true;
  }

  for (int step = 1; step <= numbers[i]; step += 1) {
    if (arrayStepper(numbers, i + step, memo)) {
      memo[i] = true;
      return true;
    }
  }
  memo[i] = false;
  return false;
}

bool arrayStepper(std::vector<int> numbers) {
  std::unordered_map<int, bool> memo;
  return arrayStepper(numbers, 0, memo); 
}
```

- n = length of numbers
- Time: O(n^2)
- Space: O(n)
